// The assignment solver is the one place in this project where an exact
// algorithm exists in two languages, so it is checked against the Python
// original rather than against hand-written expectations. The fixtures are
// generated by tests/test_optimizer.py from scipy's own answers; regenerating
// them is part of the normal `make test` run, so they cannot drift.

import { describe, expect, it } from "vitest";
import cases from "./__fixtures__/assignment_cases.json";
import {
  InfeasibleAssignmentError,
  costOfLocking,
  probKey,
  solveOptimalAssignment,
} from "./assignment";

interface FixtureCase {
  name: string;
  weeks: number[];
  teams: string[];
  probs: Record<string, number>;
  expected: {
    feasible: boolean;
    total_log_survival: number | null;
    total_survival_prob: number | null;
  };
}

// The JSON import gives TypeScript a giant literal type (576 named keys on
// one case); FixtureCase is the shape that actually matters, so widen through
// unknown rather than making the fixture file's exact keys part of the types.
const fixtures = cases as unknown as FixtureCase[];

function toMap(probs: Record<string, number>): Map<string, number> {
  return new Map(Object.entries(probs));
}

describe("solveOptimalAssignment vs. the Python solver", () => {
  it("has fixtures to check against", () => {
    expect(fixtures.length).toBeGreaterThanOrEqual(9);
  });

  for (const c of fixtures) {
    // Total cost, not the assignment itself. Ties mean several distinct
    // assignments can be equally optimal (one fixture is built entirely of
    // them), so cell-for-cell agreement with scipy would be a flaky test
    // wearing a strict test's clothes. Optimality is a property of the cost;
    // the assignment only has to be *valid* and *achieve* that cost.
    it(`matches scipy on "${c.name}"`, () => {
      const probs = toMap(c.probs);

      if (!c.expected.feasible) {
        expect(() => solveOptimalAssignment(c.weeks, c.teams, probs)).toThrow(
          InfeasibleAssignmentError,
        );
        return;
      }

      const result = solveOptimalAssignment(c.weeks, c.teams, probs);

      // Valid: one pick per week, every week covered, no team reused, and
      // every chosen cell actually present in the input.
      expect(result.picks.map((p) => p.week)).toEqual([...c.weeks].sort((a, b) => a - b));
      expect(new Set(result.picks.map((p) => p.team)).size).toBe(result.picks.length);
      for (const p of result.picks) {
        const known = probs.get(probKey(p.week, p.team));
        expect(known).toBeDefined();
        expect(p.survivalProb).toBeCloseTo(known as number, 12);
      }

      // Optimal: same total as scipy.
      expect(result.totalLogSurvival).toBeCloseTo(c.expected.total_log_survival as number, 9);
      expect(result.totalSurvivalProb).toBeCloseTo(c.expected.total_survival_prob as number, 12);

      // Internally consistent.
      const summed = result.picks.reduce((acc, p) => acc + Math.log(p.survivalProb), 0);
      expect(summed).toBeCloseTo(result.totalLogSurvival, 9);
    });
  }
});

describe("edge cases mirroring assignment.py", () => {
  it("returns the identity result for no weeks", () => {
    const r = solveOptimalAssignment([], ["A", "B"], new Map());
    expect(r.picks).toEqual([]);
    expect(r.totalSurvivalProb).toBe(1);
    expect(r.totalLogSurvival).toBe(0);
  });

  it("throws when there are fewer teams than weeks", () => {
    expect(() => solveOptimalAssignment([1, 2, 3], ["A", "B"], new Map())).toThrow(
      InfeasibleAssignmentError,
    );
  });

  it("names the week it could not fill", () => {
    const probs = new Map([[probKey(1, "A"), 0.9]]);
    try {
      solveOptimalAssignment([1, 2], ["A", "B"], probs);
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InfeasibleAssignmentError);
      expect((e as InfeasibleAssignmentError).week).toBe(2);
    }
  });

  it("treats a probability of exactly 0 as unavailable, not as a cheap pick", () => {
    const probs = new Map([
      [probKey(1, "A"), 0.0],
      [probKey(1, "B"), 0.6],
    ]);
    const r = solveOptimalAssignment([1], ["A", "B"], probs);
    expect(r.picks[0].team).toBe("B");
  });

  it("rejects a probability outside [0, 1] as a caller bug", () => {
    const probs = new Map([[probKey(1, "A"), 1.4]]);
    expect(() => solveOptimalAssignment([1], ["A"], probs)).toThrow(/must be in \[0, 1\]/);
  });

  it("prefers a globally better plan over the greedy week-by-week choice", () => {
    // Week 1 greedily takes A (0.95), leaving week 2 with B at 0.50.
    // Optimal takes B in week 1 (0.90) and A in week 2 (0.92).
    const probs = new Map([
      [probKey(1, "A"), 0.95],
      [probKey(1, "B"), 0.9],
      [probKey(2, "A"), 0.92],
      [probKey(2, "B"), 0.5],
    ]);
    const r = solveOptimalAssignment([1, 2], ["A", "B"], probs);
    expect(r.picks.map((p) => p.team)).toEqual(["B", "A"]);
    expect(r.totalSurvivalProb).toBeCloseTo(0.9 * 0.92, 12);
  });
});

describe("costOfLocking", () => {
  const weeks = [1, 2];
  const teams = ["A", "B", "C"];
  const probs = new Map([
    [probKey(1, "A"), 0.95],
    [probKey(1, "B"), 0.9],
    [probKey(1, "C"), 0.7],
    [probKey(2, "A"), 0.92],
    [probKey(2, "B"), 0.5],
    [probKey(2, "C"), 0.6],
  ]);

  it("prices the optimal cells at zero and everything else above it", () => {
    const baseline = solveOptimalAssignment(weeks, teams, probs);
    const costs = costOfLocking(weeks, teams, probs, baseline.totalLogSurvival);

    for (const p of baseline.picks) {
      expect(costs.get(probKey(p.week, p.team))).toBeCloseTo(0, 12);
    }
    for (const c of costs.values()) {
      expect(c).toBeGreaterThanOrEqual(0);
    }
    // Pinning C into week 1 forces the plan off its optimum.
    expect(costs.get(probKey(1, "C")) as number).toBeGreaterThan(0);
  });

  it("agrees with re-solving the locked problem directly", () => {
    const baseline = solveOptimalAssignment(weeks, teams, probs);
    const costs = costOfLocking(weeks, teams, probs, baseline.totalLogSurvival);

    // Lock C into week 1 by filtering, exactly as the planner does.
    const locked = new Map(
      [...probs].filter(([k]) => (k.startsWith("1:") ? k === probKey(1, "C") : k !== probKey(2, "C"))),
    );
    const withLock = solveOptimalAssignment(weeks, teams, locked);
    expect(costs.get(probKey(1, "C")) as number).toBeCloseTo(
      baseline.totalLogSurvival - withLock.totalLogSurvival,
      12,
    );
  });

  it("skips cells that are not playable at all", () => {
    const costs = costOfLocking(weeks, teams, probs, 0);
    expect(costs.has(probKey(1, "ZZ"))).toBe(false);
  });

  it("stays fast on a full-season grid", () => {
    // 18 weeks x 32 teams is the real shape, re-solved on every lock toggle.
    const bigWeeks = Array.from({ length: 18 }, (_, i) => i + 1);
    const bigTeams = Array.from({ length: 32 }, (_, i) => `T${i}`);
    const bigProbs = new Map<string, number>();
    for (const w of bigWeeks) {
      for (const t of bigTeams) bigProbs.set(probKey(w, t), 0.4 + ((w * 7 + t.length * 3) % 50) / 100);
    }
    const baseline = solveOptimalAssignment(bigWeeks, bigTeams, bigProbs);
    const started = performance.now();
    const costs = costOfLocking(bigWeeks, bigTeams, bigProbs, baseline.totalLogSurvival);
    const elapsed = performance.now() - started;

    expect(costs.size).toBe(18 * 32);
    expect(elapsed).toBeLessThan(2000);
  });
});

describe("costOfLocking restrictToWeeks", () => {
  const weeks = [1, 2, 3];
  const teams = ["A", "B", "C", "D"];
  const probs = new Map(
    weeks.flatMap((w) => teams.map((t, i) => [probKey(w, t), 0.5 + 0.05 * ((w + i) % 6)] as const)),
  );

  it("prices only the requested weeks, with identical values", () => {
    const baseline = solveOptimalAssignment(weeks, teams, probs).totalLogSurvival;
    const all = costOfLocking(weeks, teams, probs, baseline);
    const justWeek2 = costOfLocking(weeks, teams, probs, baseline, [2]);

    expect([...justWeek2.keys()].every((k) => k.startsWith("2:"))).toBe(true);
    expect(justWeek2.size).toBe(teams.length);
    for (const [k, v] of justWeek2) expect(v).toBeCloseTo(all.get(k) as number, 12);
  });

  it("prices nothing for a week that isn't in the problem", () => {
    expect(costOfLocking(weeks, teams, probs, 0, [99]).size).toBe(0);
  });
});
